challenge.solution:
const route = ["Earth", "Moon", "Mars", "Jupiter"];

// 1) insert with splice
route.splice(3, 0, "Asteroid Belt");
// 2) firstStops
const firstStops = route.slice(0, 2);
// 3) routeText
const routeText = route.join(" → ");

console.log(firstStops);
console.log(routeText);

