project_task.solution:
const inventory = ["shield", "laser"];

// 1) add a fuel cell
inventory.push("fuel cell");
// 2) remove the laser
const laserIndex = inventory.indexOf("laser");
inventory.splice(laserIndex, 1);
// 3) hasShield
const hasShield = inventory.includes("shield");
// 4) print the inventory line
console.log(`Inventory: ${inventory.join(", ")} (${inventory.length} items)`);
